    // Calculate velocity vector from a Regular_triangulation_3 cell using hyperplane geometry in 4D lifted space
    // Get the vertices of the cell
    RT::Vertex_handle v0 = c->vertex(0);
    RT::Vertex_handle v1 = c->vertex(1);
    RT::Vertex_handle v2 = c->vertex(2);
    RT::Vertex_handle v3 = c->vertex(3);

    // Calculate the coordinates of the vertices in 4D lifted space
    double x0 = rt.point(v0).x();
    double y0 = rt.point(v0).y();
    double z0 = rt.point(v0).z();
    double w0 = time;
    double x1 = rt.point(v1).x();
    double y1 = rt.point(v1).y();
    double z1 = rt.point(v1).z();
    double w1 = time;
    double x2 = rt.point(v2).x();
    double y2 = rt.point(v2).y();
    double z2 = rt.point(v2).z();
    double w2 = time;
    double x3 = rt.point(v3).x();
    double y3 = rt.point(v3).y();
    double z3 = rt.point(v3).z();
    double w3 = time;

    // Calculate the hyperplane of the cell in 4D lifted space
    LiftedPoint p0 = lifted_point(x0, y0, z0, w0);
    LiftedPoint p1 = lifted_point(x1, y1, z1, w1);
    LiftedPoint p2 = lifted_point(x2, y2, z2, w2);
    LiftedPoint p3 = lifted_point(x3, y3, z3, w3);
